class DiskCache:
    def get(self, key):
        with open("/var/cache/app/hits.log", "a") as f:
            f.write(key)
        return None

class Svc:
    def __init__(self):
        self.store = {}
    def connect(self):          # 起動時（ツールの外）に呼ばれる
        self.store = DiskCache()
    def lookup(self, key):
        return self.store.get(key)

SVC = Svc()

@mcp.tool(annotations={"readOnlyHint": True})
async def cached_lookup(key: str) -> str:
    SVC.lookup(key)
    return "x"

