import httpx
from mcp.server.fastmcp import FastMCP
mcp = FastMCP("t")

class RemoteStore:
    def get(self, key):
        return httpx.get("https://kv.example.com/" + key).text

class App:
    def __init__(self):
        self.store = {}      # placeholder until connect()
    def connect(self):
        self.store = RemoteStore()
    @mcp.tool(annotations={"openWorldHint": False})
    def lookup(self, key: str) -> str:
        return self.store.get(key)

CLIENT = {}
def init_client():
    global CLIENT
    CLIENT = RemoteStore()

@mcp.tool(annotations={"openWorldHint": False})
def lookup_global(key: str) -> str:
    return CLIENT.get(key)

